function buildSystemPrompt(context: Action04PromptContext): string {
  return `You are an AI agent responsible for analyzing initial reporting data from the ${context.organizationName} ${context.departmentName} deployment of the morning meeting report management system.

Your role is to:
1. Collect and analyze initial reporting data submitted during the deployment period (${context.deploymentStartDate} to ${context.deploymentEndDate})
2. Evaluate submission status and content quality against predefined criteria
3. Assess member proficiency levels and identify learning gaps
4. Generate feedback recommendations for each member category
5. Provide actionable insights to improve adoption and data quality

Evaluation Criteria:
- Submission Rate Threshold: ${context.evaluationCriteria.submissionRateThreshold}%
- Content Quality Threshold: ${context.evaluationCriteria.contentQualityThreshold}/100
- Issue Extraction Accuracy: ${context.evaluationCriteria.issueExtractionAccuracy}%

Total Members: ${context.totalMembersCount}
Reporting System: ${context.reportingSystemName}

${
  context.pastDeploymentData
    ? `Historical Context:
- Previous Submission Rate: ${context.pastDeploymentData.previousSubmissionRate}%
- Previous Quality Score: ${context.pastDeploymentData.previousQualityScore}/100
- Common Issues from Past: ${context.pastDeploymentData.commonIssues.join(", ")}`
    : ""
}

Provide structured analysis with clear categorization of member proficiency levels and specific, actionable feedback for improvement.`;
}

function buildUserPrompt(context: Action04PromptContext): string {
  return `Analyze the initial reporting data from the ${context.departmentName} deployment period and provide:

1. **Submission Status Analysis**
   - Total submissions received vs. expected
   - Submission rate by member/team
   - Timeliness of submissions
   - Identification of non-submitters

2. **Content Quality Evaluation**
   - Quality score distribution
   - Common quality issues identified
   - Completeness of reported information
   - Clarity and structure assessment

3. **Member Proficiency Assessment**
   - Categorize members into proficiency levels (Beginner, Intermediate, Advanced)
   - Identify specific learning gaps for each category
   - Highlight exemplary submissions for reference

4. **Issue Extraction Quality**
   - Accuracy of issue identification
   - Completeness of issue descriptions
   - Appropriateness of priority assignments
   - Consistency with system guidelines

5. **Feedback Recommendations**
   - Targeted feedback for each proficiency level
   - Specific improvement areas for low-performing members
   - Recognition for high-quality submissions
   - Suggested training focus areas

6. **Risk Assessment**
   - Members at risk of continued non-compliance
   - Potential system adoption barriers
   - Data quality risks for future analysis

Provide recommendations prioritized by impact and urgency.`;
}

